INSERT INTO cards (id, name_ru, arcana, suit, upright_ru, reversed_ru, image_key) VALUES
  (0, 'Дурак', 'major', NULL, 'Новое начало, шаг в неизвестность. Легкость и доверие пути.', 'Безрассудство или страх сделать шаг. Проверь, что держит.', 'cards/major-00-fool.webp'),
  (1, 'Маг', 'major', NULL, 'Воля и ресурсы: всё нужное уже в руках. Время действовать.', 'Манипуляция или нерешительность. Собери фокус в одно дело.', 'cards/major-01-magician.webp'),
  (2, 'Верховная Жрица', 'major', NULL, 'Интуиция и тишина. Ответ уже внутри — дай ему дозреть.', 'Заглушенный внутренний голос. Меньше шума, больше пауз.', 'cards/major-02-priestess.webp'),
  (3, 'Императрица', 'major', NULL, 'Изобилие и забота. Питай дело и людей — растет.', 'Застой или гиперопека. Отпусти контроль, верни меру.', 'cards/major-03-empress.webp'),
  (4, 'Император', 'major', NULL, 'Структура и порядок. Правила и границы держат дело.', 'Ригидность или давление. Структура служит тебе, не наоборот.', 'cards/major-04-emperor.webp'),
  (5, 'Иерофант', 'major', NULL, 'Традиция и наставник. Опора на проверенное знание.', 'Догмы или бунт ради бунта. Отдели смысл от формы.', 'cards/major-05-hierophant.webp'),
  (6, 'Влюбленные', 'major', NULL, 'Выбор сердцем и честный союз. Ценности совпадают.', 'Дисгармония или неверный выбор. Вернись к ценностям.', 'cards/major-06-lovers.webp'),
  (7, 'Колесница', 'major', NULL, 'Движение и победа воли. Держи вожжи — едем.', 'Пробуксовка или потеря направления. Остановись и перенацелься.', 'cards/major-07-chariot.webp'),
  (8, 'Сила', 'major', NULL, 'Мягкая сила и терпение. Спокойствие сильнее рывка.', 'Неуверенность или подавление себя. Дай себе опору.', 'cards/major-08-strength.webp'),
  (9, 'Отшельник', 'major', NULL, 'Пауза и внутренний свет. Уединение ради ясности.', 'Изоляция или уход от людей. Пауза — да, стена — нет.', 'cards/major-09-hermit.webp'),
  (10, 'Колесо Фортуны', 'major', NULL, 'Поворот цикла. Волна идет — встань на нее.', 'Сопротивление переменам. Отпусти весло, держи курс.', 'cards/major-10-wheel.webp'),
  (11, 'Справедливость', 'major', NULL, 'Честность и последствия. Поступки возвращаются.', 'Несправедливость или самообман. Назови вещи своими именами.', 'cards/major-11-justice.webp'),
  (12, 'Повешенный', 'major', NULL, 'Пауза и смена ракурса. Повиси — увидишь иначе.', 'Жертва без смысла или топтание. Выходи из подвеса решением.', 'cards/major-12-hanged.webp'),
  (13, 'Смерть', 'major', NULL, 'Завершение и трансформация. Старое уходит — место новому.', 'Цепляние за прошлое. Отпустить — тоже действие.', 'cards/major-13-death.webp'),
  (14, 'Умеренность', 'major', NULL, 'Баланс и мера. Тихий средний путь держит.', 'Крайности и дисбаланс. Верни ритм и дозу.', 'cards/major-14-temperance.webp'),
  (15, 'Дьявол', 'major', NULL, 'Тень и зависимость. Назови привязанность — ослабнет.', 'Освобождение от пут. Цепь уже рвется — помоги.', 'cards/major-15-devil.webp'),
  (16, 'Башня', 'major', NULL, 'Рушится ложное. Больно, но освобождает место правде.', 'Оттягивание неизбежного. Лучше малая трещина, чем обвал.', 'cards/major-16-tower.webp'),
  (17, 'Звезда', 'major', NULL, 'Надежда и исцеление. Тихий свет ведет.', 'Угасание веры. Маленький ритуал вернет огонь.', 'cards/major-17-star.webp'),
  (18, 'Луна', 'major', NULL, 'Туман и страхи. Не все тени реальны — иди медленно.', 'Прояснение. Туман расходится, дорога видна.', 'cards/major-18-moon.webp'),
  (19, 'Солнце', 'major', NULL, 'Ясность и радость. День твой — свети.', 'Временная облачность. Солнце за тучей, не погасло.', 'cards/major-19-sun.webp'),
  (20, 'Суд', 'major', NULL, 'Пробуждение и зов. Пора встать и ответить.', 'Самобичевание или глухота. Прости прошлое, услышь зов.', 'cards/major-20-judgement.webp'),
  (21, 'Мир', 'major', NULL, 'Завершение цикла и целостность. Круг замкнулся.', 'Незавершенность. Остался последний шаг — сделай.', 'cards/major-21-world.webp');
INSERT INTO cards (id, name_ru, arcana, suit, upright_ru, reversed_ru, image_key) VALUES
  (22, 'Туз Жезлов', 'minor', 'wands', 'Искра и шанс. Хватай импульс, начинай.', 'Ложный старт или выгорание искры. Подожди топливо.', 'cards/minor-wands-ace.webp'),
  (23, 'Двойка Жезлов', 'minor', 'wands', 'Выбор направления. Мир шире планов.', 'Нерешительность или мелкий план. Подними взгляд.', 'cards/minor-wands-02.webp'),
  (24, 'Тройка Жезлов', 'minor', 'wands', 'Первые ростки. Корабли уже в пути.', 'Задержка результатов. Проверь курс, не паникуй.', 'cards/minor-wands-03.webp'),
  (25, 'Четверка Жезлов', 'minor', 'wands', 'Праздник и опора. Есть что отметить.', 'Шаткий фундамент праздника. Укрепи базу.', 'cards/minor-wands-04.webp'),
  (26, 'Пятерка Жезлов', 'minor', 'wands', 'Спор и конкуренция. Трение точит мастерство.', 'Конфликт без правил. Выйди из свары.', 'cards/minor-wands-05.webp'),
  (27, 'Шестерка Жезлов', 'minor', 'wands', 'Признание и победа. Прими аплодисменты.', 'Самопиар без дела. Пусть говорит результат.', 'cards/minor-wands-06.webp'),
  (28, 'Семерка Жезлов', 'minor', 'wands', 'Оборона позиции. Ты выше — держи высоту.', 'Сдача без боя. Позиция стоит усилий.', 'cards/minor-wands-07.webp'),
  (29, 'Восьмерка Жезлов', 'minor', 'wands', 'Скорость и новости. Стрелы уже летят.', 'Спешка и перегруз каналами. Приоритизируй.', 'cards/minor-wands-08.webp'),
  (30, 'Девятка Жезлов', 'minor', 'wands', 'Стойкость на последнем рубеже. Почти дошел.', 'Истощение обороны. Попроси подкрепление.', 'cards/minor-wands-09.webp'),
  (31, 'Десятка Жезлов', 'minor', 'wands', 'Ноша и перегруз. Неси только свое.', 'Сбрось лишнее. Делегируй или откажи.', 'cards/minor-wands-10.webp'),
  (32, 'Паж Жезлов', 'minor', 'wands', 'Весть и ученичество. Любопытство зовет.', 'Поверхностный энтузиазм. Копни глубже.', 'cards/minor-wands-page.webp'),
  (33, 'Рыцарь Жезлов', 'minor', 'wands', 'Рывок и азарт. Вперед, но смотри под ноги.', 'Порыв без тормозов. Придержи коней.', 'cards/minor-wands-knight.webp'),
  (34, 'Королева Жезлов', 'minor', 'wands', 'Теплая уверенность. Веди за собой.', 'Ревность или выгорание сцены. Отдохни.', 'cards/minor-wands-queen.webp'),
  (35, 'Король Жезлов', 'minor', 'wands', 'Лидерство и видение. Зажигай других.', 'Деспотизм или позерство. Веди примером.', 'cards/minor-wands-king.webp');
INSERT INTO cards (id, name_ru, arcana, suit, upright_ru, reversed_ru, image_key) VALUES
  (36, 'Туз Кубков', 'minor', 'cups', 'Новое чувство. Сердце открывается.', 'Переполненность или закрытость. Дай чувствам сосуд.', 'cards/minor-cups-ace.webp'),
  (37, 'Двойка Кубков', 'minor', 'cups', 'Встреча и союз. Равный обмен.', 'Разлад или неравный обмен. Выровняй.', 'cards/minor-cups-02.webp'),
  (38, 'Тройка Кубков', 'minor', 'cups', 'Дружба и радость. Празднуй с близкими.', 'Сплетни или thirdwheel. Выбери круг.', 'cards/minor-cups-03.webp'),
  (39, 'Четверка Кубков', 'minor', 'cups', 'Апатия и переоценка. Чаша рядом — подними глаза.', 'Выход из хандры. Протяни руку.', 'cards/minor-cups-04.webp'),
  (40, 'Пятерка Кубков', 'minor', 'cups', 'Потеря и скорбь. Две чаши стоят — оглянись.', 'Принятие утраты. Пора поднять уцелевшие.', 'cards/minor-cups-05.webp'),
  (41, 'Шестерка Кубков', 'minor', 'cups', 'Тепло прошлого. Добрые корни питают.', 'Застревание в ностальгии. Прошлое — гость, не дом.', 'cards/minor-cups-06.webp'),
  (42, 'Семерка Кубков', 'minor', 'cups', 'Миражи вариантов. Выбери одну чашу.', 'Туман рассеивается. Решение близко.', 'cards/minor-cups-07.webp'),
  (43, 'Восьмерка Кубков', 'minor', 'cups', 'Уход к смыслу. Оставь мелкое ради главного.', 'Топтание у берега. Уходи или вернись.', 'cards/minor-cups-08.webp'),
  (44, 'Девятка Кубков', 'minor', 'cups', 'Желание сбывается. Наслаждайся заслуженным.', 'Каприз вместо желания. Проверь истинность.', 'cards/minor-cups-09.webp'),
  (45, 'Десятка Кубков', 'minor', 'cups', 'Полнота и гармония дома. Счастье рядом.', 'Разлад в близком кругу. Поговори честно.', 'cards/minor-cups-10.webp'),
  (46, 'Паж Кубков', 'minor', 'cups', 'Нежная весть. Чувствительность — сила.', 'Обидчивость. Не читай между строк.', 'cards/minor-cups-page.webp'),
  (47, 'Рыцарь Кубков', 'minor', 'cups', 'Романтичный порыв. Следуй сердцу с умом.', 'Пустые обещания. Проверяй делами.', 'cards/minor-cups-knight.webp'),
  (48, 'Королева Кубков', 'minor', 'cups', 'Глубокая эмпатия. Слушай и держи.', 'Эмоциональное утопление. Береги берега.', 'cards/minor-cups-queen.webp'),
  (49, 'Король Кубков', 'minor', 'cups', 'Зрелость чувств. Штиль внутри шторма.', 'Манипуляция чувствами. Держи ровность.', 'cards/minor-cups-king.webp');
INSERT INTO cards (id, name_ru, arcana, suit, upright_ru, reversed_ru, image_key) VALUES
  (50, 'Туз Мечей', 'minor', 'swords', 'Ясность мысли. Режь правдой — точно.', 'Путаница или резкость. Наточи мысль.', 'cards/minor-swords-ace.webp'),
  (51, 'Двойка Мечей', 'minor', 'swords', 'Пауза и напряжение выбора. Сними повязку.', 'Выход из тупика. Решение назрело.', 'cards/minor-swords-02.webp'),
  (52, 'Тройка Мечей', 'minor', 'swords', 'Боль и правда. Проживи, не глуши.', 'Заживление раны. Боль отпускает.', 'cards/minor-swords-03.webp'),
  (53, 'Четверка Мечей', 'minor', 'swords', 'Отдых и восстановление. Тишина лечит.', 'Выход из паузы. Пора вставать.', 'cards/minor-swords-04.webp'),
  (54, 'Пятерка Мечей', 'minor', 'swords', 'Пиррова победа. Цена важнее трофея.', 'Примирение после битвы. Сложи оружие.', 'cards/minor-swords-05.webp'),
  (55, 'Шестерка Мечей', 'minor', 'swords', 'Переход к спокойствию. Лодка уже плывет.', 'Застревание в шторме. Греби к берегу.', 'cards/minor-swords-06.webp'),
  (56, 'Семерка Мечей', 'minor', 'swords', 'Хитрость и стратегия. Проверь честность пути.', 'Разоблачение уловки. Играй открыто.', 'cards/minor-swords-07.webp'),
  (57, 'Восьмерка Мечей', 'minor', 'swords', 'Самоограничение. Веревки слабее, чем кажутся.', 'Освобождение. Шаг — и путы спадут.', 'cards/minor-swords-08.webp'),
  (58, 'Девятка Мечей', 'minor', 'swords', 'Ночная тревога. Утро меняет масштаб.', 'Рассвет после бессонницы. Страх тает.', 'cards/minor-swords-09.webp'),
  (59, 'Десятка Мечей', 'minor', 'swords', 'Дно и финал. Хуже не будет — вставай.', 'Подъем со дна. Раны затягиваются.', 'cards/minor-swords-10.webp'),
  (60, 'Паж Мечей', 'minor', 'swords', 'Острый ум и весть. Проверяй факты.', 'Сплетня или поспешность. Придержи язык.', 'cards/minor-swords-page.webp'),
  (61, 'Рыцарь Мечей', 'minor', 'swords', 'Стремительный рывок мысли. Руби точно.', 'Безрассудная атака. Целься, не маши.', 'cards/minor-swords-knight.webp'),
  (62, 'Королева Мечей', 'minor', 'swords', 'Ясный взгляд. Честность без жестокости.', 'Холодность или язвительность. Смягчи.', 'cards/minor-swords-queen.webp'),
  (63, 'Король Мечей', 'minor', 'swords', 'Разум и справедливость. Решай трезво.', 'Манипуляция логикой. Проверь мотивы.', 'cards/minor-swords-king.webp');
INSERT INTO cards (id, name_ru, arcana, suit, upright_ru, reversed_ru, image_key) VALUES
  (64, 'Туз Пентаклей', 'minor', 'pentacles', 'Шанс в материальном. Сажай семя.', 'Упущенная выгода. Не проспи шанс.', 'cards/minor-pentacles-ace.webp'),
  (65, 'Двойка Пентаклей', 'minor', 'pentacles', 'Баланс дел. Жонглируй гибко.', 'Перегруз жонглированием. Урони лишнее.', 'cards/minor-pentacles-02.webp'),
  (66, 'Тройка Пентаклей', 'minor', 'pentacles', 'Мастерство и команда. Строй вместе.', 'Плохая работа или разлад. Проверь качество.', 'cards/minor-pentacles-03.webp'),
  (67, 'Четверка Пентаклей', 'minor', 'pentacles', 'Удержание и контроль. Держи, но не души.', 'Скупость или расточительность. Ослабь хватку.', 'cards/minor-pentacles-04.webp'),
  (68, 'Пятерка Пентаклей', 'minor', 'pentacles', 'Нужда и холод. Помощь рядом — попроси.', 'Выход из нужды. Тепло возвращается.', 'cards/minor-pentacles-05.webp'),
  (69, 'Шестерка Пентаклей', 'minor', 'pentacles', 'Обмен и помощь. Давай и принимай.', 'Дисбаланс дарения. Выровняй счет.', 'cards/minor-pentacles-06.webp'),
  (70, 'Семерка Пентаклей', 'minor', 'pentacles', 'Терпеливое ожидание урожая. Оцени всходы.', 'Нетерпение или плохой урожай. Пересей.', 'cards/minor-pentacles-07.webp'),
  (71, 'Восьмерка Пентаклей', 'minor', 'pentacles', 'Ремесло и усердие. Мастерство растет.', 'Халтура или рутина. Верни внимание.', 'cards/minor-pentacles-08.webp'),
  (72, 'Девятка Пентаклей', 'minor', 'pentacles', 'Достаток и самодостаточность. Наслаждайся садом.', 'Зависимость от достатка. Свобода дороже.', 'cards/minor-pentacles-09.webp'),
  (73, 'Десятка Пентаклей', 'minor', 'pentacles', 'Наследие и стабильность рода. Строй надолго.', 'Семейный разлад о материальном. Люди важнее.', 'cards/minor-pentacles-10.webp'),
  (74, 'Паж Пентаклей', 'minor', 'pentacles', 'Ученичество в деле. Маленький шаг к большому.', 'Упущенный шанс учиться. Начни с малого.', 'cards/minor-pentacles-page.webp'),
  (75, 'Рыцарь Пентаклей', 'minor', 'pentacles', 'Надежное движение. Медленно, но верно.', 'Топтание или упрямство. Проверь маршрут.', 'cards/minor-pentacles-knight.webp'),
  (76, 'Королева Пентаклей', 'minor', 'pentacles', 'Заботливое изобилие. Дом и дело в порядке.', 'Перегруз заботой о других. Позаботься о себе.', 'cards/minor-pentacles-queen.webp'),
  (77, 'Король Пентаклей', 'minor', 'pentacles', 'Мастер материального. Надежность и щедрость.', 'Скупость или трудоголизм. Деньги — средство.', 'cards/minor-pentacles-king.webp');
